:root {
    /* Colors */
    --color-primary: #192f7a;
    --color-dark-gray: rgb(37, 37, 37);
    --color-medium-gray: rgb(66, 66, 66);
    --color-lightest-gray: rgb(215, 215, 215);

    /* Font */
    --font-sans: Calibri, Candara, Segoe, "Segoe UI", Optima, Arial, sans-serif;
}

@page {
    /* 20 cm wide × 27.5 cm tall paper */
    size: 20cm 27.5cm;
    margin: 0;
}

html, body {
    margin: 0;
    padding: 0;
    font-family: var(--font-sans);
}

@media print {
    * {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
    /* Pin the cheque block to the bottom 7.5 cm of the page */
    .cheque-house {
        position: fixed;
        bottom: 0;      /* bottom of the 27.5 cm page */
        left: 1cm;      /* match the master-container gutter */
        right: 1cm;
        height: 7.5cm;  /* remaining space */
    }

    .cheque-house {
    border: none !important;
    padding: 5pt;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    font-size: 11pt;
    }

}

body {
    border-width: 1pt;
    padding-left: 15pt;
    padding-right: 15pt;
}

/* ─── Top 20 cm zone: voucher details ─────────────────────────────────────── */
.master-container {
    height: 20cm;            /* fixed top zone height */
    box-sizing: border-box;  /* include padding in that height */
    padding: 1cm;            /* your 1 cm gutters */
    overflow: hidden;        /* clip any extra rows */
    position: relative;      /* anchor for cheque-house */
}

.logo-container {
    margin-top: 20pt;
}

.company-details {
    font-size: 7pt;
    color: var(--color-dark-gray);
    font-weight: 400;
}

.header {
    display: flex;
    justify-content: flex-end;
    align-items: flex-start;
}

.section-break {
    margin: 10pt 0 !important;
}

.title {
    font-size: 30pt;
    font-weight: 600;
    color: var(--color-primary);
    text-align: right;
    margin: 0 !important;
}

.title.so-series {
    font-size: 15pt;
    font-weight: 100;
    color: var(--color-dark-gray);
    margin-top: -5pt !important;
    letter-spacing: 0;
}

.contact-information {
    display: flex;
    justify-content: space-between;
}

.info-block {
    display: flex;
    vertical-align: top;
}

.info-block tr {
    font-size: 10pt;
    font-weight: 800;
    color: rgb(58, 58, 58);
}

td.label-unique {
    padding-right: 10pt !important;
}

/* ─── Order Details Tables ───────────────────────────────────────────────── */
.entry-rows {
    font-size: 8pt;
}

.order-details {
    width: 100%;
    margin-top: 15pt;
    margin-bottom: 10pt;
    border-collapse: collapse;
    table-layout: fixed;
    font-size: 11pt;
}

.order-details th,
.order-details td {
    border: 1px solid var(--color-dark-gray);
    padding: 0.5em !important;
    word-wrap: break-word;
    white-space: normal;
}

.order-details th:nth-child(1),
.order-details td:nth-child(1) { width: 75%; }
.order-details th:nth-child(2),
.order-details td:nth-child(2) { width: 25%; }

.order-details th {
    background-color: lightgray;
    color: black;
    font-size: 10pt;
    font-weight: 600;
    padding: 3pt 8pt;
    border-bottom: 2px solid #005580;
}

.last-row {
    text-align: right;
}

.input-signature {
    margin-top: 0.5cm;
    text-align: center;
}

.flex-this {
    display: flex;
}

.input-line-1 {
    margin-bottom: -13pt;
    margin-top:0.3cm;
}

.input-line-2 {
    margin-bottom: -13pt;
    margin-top:0.3cm;
}

/* ─── Signatures & Amount-in-Words ────────────────────────────────────────── */
.transaction-details-container {
    display: flex;
    justify-content: space-between;
    margin-bottom: 10pt;
    font-size: 10pt;
}

.signature-container {
    display: flex;
    gap: 20pt;
    margin-bottom: 0;
}

/* ─── Bottom 7.5 cm zone: cheque layout ───────────────────────────────────── */
.cheque-house {
    border: none !important;
    padding: 5pt;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    font-size: 11pt;
}

.cheque-date,
.cheque-word {
    font-size: 10pt;
}

.cheque-name-amount {
    display: flex;
    justify-content: space-between;
    font-size: 12pt;
}

.cheque-date {
    position: absolute;
    bottom: 5.5cm;
    right: 0.2cm;
    letter-spacing: .6em;
}

.paid-amount {
    position: absolute;
    bottom: 4.7cm;
    right: 3cm;
}

.party-name {
    position: absolute;
    bottom: 4.7cm;
    left: 3cm;
}

.cheque-inword {
    position: absolute;
    bottom: 3.7cm;
    left: 2cm;
}


.approval {
    margin-top: 0.7cm;
}

.signatories-container {
    padding-left: 1cm;
    width:12cm;
}

.received-text{
    margin-top: 0.1cm;
}
